function mkEstimate(over = {}) {
  return {
    number: "",
    date: "",
    validThrough: "",
    status: "Draft",
    scope: "",
    notes: "",
    items: [],
    /* Good/Better/Best + optional upgrades. Deliberately additive:
       `items` stays the single flattened list every existing reader
       (estimateTotal, the PDF/doc builder, financials, commission calc,
       the portal) already reads — none of that had to change. `tiers`
       and `upgrades` are the AUTHORING structure; selecting a tier or
       toggling an upgrade re-flattens into `items` via
       applyEstimateSelection(). A job with no tiers configured (every
       existing job, until a rep sets this up) behaves exactly as
       before — tiers defaults to [], so applyEstimateSelection is a
       no-op and items is untouched. */
    tiers: [],
    // [{ id, name, items: [...same shape as items] }]
    selectedTier: null,
    // id of the active tier, or null = flat estimate (old behavior)
    upgrades: [],
    // [{ id, desc, price, cost, selected }]
    concealed: [
      { id: "c1", desc: 'Roof decking replacement (7/16" OSB)', unit: "per 4\xD78 sheet", price: 0, on: true },
      { id: "c2", desc: "Plank decking replacement", unit: "per LF", price: 0, on: true },
      { id: "c3", desc: "Rafter sistering / repair", unit: "per rafter", price: 0, on: true },
      { id: "c4", desc: "Fascia replacement", unit: "per LF", price: 0, on: true }
    ],
    clientSig: null,
    sigAt: null,
    ...over
  };
}
function applyEstimateSelection(est) {
  const tiers = est.tiers || [];
  const tier = tiers.find((t) => t.id === est.selectedTier);
  const base = tier ? tier.items : est.items;
  const upgrades = (est.upgrades || []).filter((u) => u.selected);
  const upgradeItems = upgrades.map((u) => ({
    id: u.id,
    desc: u.desc,
    qty: 1,
    unit: "ea",
    price: num(u.price),
    cost: num(u.cost),
    fromUpgrade: true
  }));
  return [...base, ...upgradeItems];
}
function catalogUnitPrice(priceList, keywords, factor) {
  if (!Array.isArray(priceList) || !priceList.length) return null;
  const hit = priceList.find((r) => {
    const hay = `${r.item || ""} ${r.sku || ""} ${r.category || ""}`.toLowerCase();
    return keywords.some((k) => hay.includes(k));
  });
  const base = hit ? num(hit.price) : 0;
  if (!base) return null;
  return Math.round(base * factor * 100) / 100;
}
